#!/bin/bash
set -e

echo "=== Aggiorno la copertina Mare e Foce con il banner app ==="

mkdir -p public/covers

base64 -d > public/covers/mare-e-foce.jpg << 'MAREEOF'

MAREEOF

echo "=== Copertina aggiornata: public/covers/mare-e-foce.jpg ==="
echo ""
echo "Ricorda: bash aggiorna-copertina-mare-banner.sh, poi:"
echo "git add -A && git commit -m 'aggiunge banner app alla copertina mare e foce' && git push"
